package org.kanger;
import java.util.*;
import org.kanger.ContextProductionCapture.Source;
import org.kanger.ContextProductionCapture.Support;
import org.kanger.ContextProductionCapture.Clause;
import org.kanger.ContextProductionNativeBinding.Entry;
import org.kanger.ContextProductionNativeBinding.Snapshot;
import org.kanger.ContextWitnessResultTransport.*;
import org.kanger.ContextRelationalInterpretation.*;
import org.kanger.ContextSignedRelationalModelSearch.*;
import org.kanger.ContextUniversalInputResiduals.Residual;
/** Direct formula and ACTUAL final-carrier audit. Never calls model search or its manifest builder. */
final class ContextSignedRelationalModelAudit {
 static final class OriginalReceipt {final Ledger ledger;private OriginalReceipt(Ledger l){ledger=l;}}
 static final class FinalReceipt {final Ledger ledger;final OriginalReceipt original;private FinalReceipt(Ledger l,OriginalReceipt o){ledger=l;original=o;}}
 private static void require(boolean b,String s){if(!b)throw new IllegalStateException(s);}
 private static int fixed(ContextRelationalInterpretation m,SemanticTermSnapshot value,Runnable w){require(value!=null,"Actual typed constant required");for(int i=0;i<m.points.size();i++){w.run();if(m.points.get(i).semanticallyEquals(value))return i;}throw new IllegalStateException("Complete named constant basis required");}
 private static Table relation(ContextRelationalInterpretation m,String name,int arity,Set<Signature> vocabulary,Runnable w){w.run();Signature s=new Signature(name,arity);vocabulary.add(s);Table t=m.relations.get(s);require(t!=null,"Every exact name/arity signature required");return t;}
 private static void model(ContextRelationalInterpretation m,ContextSignedUnaryModelSearch.Policy p,Runnable w){require(m!=null&&!m.points.isEmpty()&&m.points.size()<=p.original.points&&m.relations.size()<=p.original.predicates,"Bounded explicit relational model required");for(int i=0;i<m.points.size();i++){w.run();require(m.points.get(i)!=null,"Ordinary named value required");for(int j=0;j<i;j++){w.run();require(!m.points.get(i).semanticallyEquals(m.points.get(j)),"Distinct semantic basis, never Origin inequality");}}for(Map.Entry<Signature,Table> e:m.relations.entrySet()){w.run();Signature s=e.getKey();Table t=e.getValue();require(s!=null&&s.name!=null&&!s.name.isEmpty()&&s.name.length()<=256&&s.arity>=0&&t!=null&&t.exceptions.size()<=p.cells,"Bounded complete relation table required");for(Map.Entry<List<Integer>,Boolean> row:t.exceptions.entrySet()){require(row.getKey()!=null&&row.getKey().size()==s.arity&&row.getValue()!=null,"Exact tuple arity and truth required");for(Integer v:row.getKey()){w.run();require(v!=null&&v>=0&&v<=m.points.size(),"Every coordinate must include named/ALL-other class");}}}}
 private static void shape(Entry e,ContextRelationalInterpretation m,Set<Signature> vocabulary,Set<Binder> witnesses,Runnable w){w.run();if(e.bundle!=null){ContextWitnessBundle.Bundle b=e.bundle;require(e.kind==org.kanger.ContextProductionNativeBinding.Kind.WITNESS_BUNDLE&&e.clauses.isEmpty()&&b.source.equals(e.source)&&b.witnesses>0&&b.witnesses<=4&&!b.atoms.isEmpty()&&b.atoms.size()<=8,"Whole original bounded relational bundle required");Set<Integer> used=new HashSet<>();for(int binder=0;binder<b.witnesses;binder++){w.run();Binder key=new Binder(e.source,binder);require(witnesses.add(key),"Unique Source/binder choice required");Integer point=m.witnesses.get(key);require(point!=null&&point>=0&&point<m.points.size(),"Concrete original Source/binder witness required");}for(ContextWitnessBundle.Atom a:b.atoms){relation(m,a.predicate,a.arguments.size(),vocabulary,w);for(ContextWitnessBundle.Slot s:a.arguments){w.run();require(s.witness>=-1&&s.witness<b.witnesses,"Exact original binder slot required");if(s.witness>=0){require(s.value==null,"Binder cannot alias a constant");used.add(s.witness);}else fixed(m,s.value,w);}}require(used.size()==b.witnesses,"EVERY original binder must occur");}else{require(e.kind==org.kanger.ContextProductionNativeBinding.Kind.CLAUSES&&!e.clauses.isEmpty()&&e.clauses.size()<=8,"Whole original clause row required");for(Clause c:e.clauses){w.run();require(c!=null&&!c.literals.isEmpty()&&c.literals.size()<=8,"Complete original relational clause required");Set<Integer> ids=new HashSet<>();for(org.kanger.ContextProductionCapture.Atom a:c.literals){relation(m,a.predicate,a.arguments.size(),vocabulary,w);for(org.kanger.ContextProductionCapture.Slot s:a.arguments){w.run();require(s.variable>=-1,"Valid original variable slot required");if(s.variable>=0){require(s.value==null,"Variable cannot alias constant");ids.add(s.variable);}else fixed(m,s.value,w);}}require(ids.equals(c.variables),"All original variable identities required");}}}
 private static boolean originalClause(Clause c,ContextRelationalInterpretation m,Map<Integer,Integer> assignment,Runnable w){boolean yes=false;for(org.kanger.ContextProductionCapture.Atom a:c.literals){List<Integer> tuple=new ArrayList<>();for(org.kanger.ContextProductionCapture.Slot s:a.arguments){w.run();tuple.add(s.variable>=0?assignment.get(s.variable):fixed(m,s.value,w));}yes|=m.relations.get(new Signature(a.predicate,a.arguments.size())).holds(tuple,w)==a.positive;}return yes;}
 private static void originalTruth(Entry e,ContextRelationalInterpretation m,Runnable w){w.run();if(e.bundle!=null){for(ContextWitnessBundle.Atom a:e.bundle.atoms){List<Integer> tuple=new ArrayList<>();for(ContextWitnessBundle.Slot s:a.arguments){w.run();tuple.add(s.witness>=0?m.witnesses.get(new Binder(e.source,s.witness)):fixed(m,s.value,w));}require(m.relations.get(new Signature(a.predicate,a.arguments.size())).holds(tuple,w)==a.positive,"Whole correlated relational bundle false");}return;}
  for(Clause c:e.clauses){boolean uniform=true,knownTrue=false;for(org.kanger.ContextProductionCapture.Atom a:c.literals){w.run();Table t=m.relations.get(new Signature(a.predicate,a.arguments.size()));uniform&=t.exceptions.isEmpty();knownTrue|=t.exceptions.isEmpty()&&t.otherwise==a.positive;}if(knownTrue)continue;require(!uniform,"Uniform relational original clause false");
   // Explicit-stack DFS: no recursion limit proportional to variable count.
   List<Integer> ids=new ArrayList<>(c.variables);int[] positions=new int[ids.size()];Map<Integer,Integer> assignment=new HashMap<>();int level=0;while(level>=0){w.run();if(level==ids.size()){require(originalClause(c,m,assignment,w),"Cartesian original relation clause false");level--;if(level>=0)positions[level]++;continue;}if(positions[level]>m.points.size()){assignment.remove(ids.get(level));level--;if(level>=0)positions[level]++;continue;}assignment.put(ids.get(level),positions[level]);level++;if(level<ids.size())positions[level]=0;}
  }
 }
 static OriginalReceipt original(Ledger l,int maximumWork){require(l!=null&&l.branch!=null&&l.policy!=null&&maximumWork>0,"Exact relational original ledger required");Runnable w=ContextGroundProductionRounds.budget(maximumWork);ContextSignedWitnessNativeBranch.Receipt b=l.branch;List<Snapshot> cuts=new ArrayList<>();cuts.add(b.x);cuts.addAll(b.foreign);Set<Cut> expected=new LinkedHashSet<>();Set<UUID> physical=new HashSet<>();Set<Source> sources=new HashSet<>();int index=0;for(int i=0;i<cuts.size();i++){Snapshot cut=cuts.get(i);ContextProductionFamilyAssembly.identity(cut,i==0,w);ContextProductionFamilyAssembly.claimContexts(cut,physical,w);require(expected.add(Cut.of(cut)),"Unique original logical cuts required");for(Snapshot member:cut.physicalMembers())for(Entry e:member.primary){w.run();require(index<l.rows.size()&&index<l.policy.original.rows&&sources.add(e.source),"Complete unique original physical rows required");Row row=l.rows.get(index++);require(row!=null&&row.cut==cut&&row.member==member&&row.entry==e,"Different original physical row/cut/Source");}}require(index==l.rows.size()&&l.models.keySet().equals(expected),"No lost/extra original rows or model cuts");
  int tables=0,exceptions=0,witnessCount=0;for(ContextRelationalInterpretation m:l.models.values()){require(m!=null,"Complete relational model cut required");for(Binder key:m.witnesses.keySet()){w.run();require(++witnessCount<=l.policy.witnesses,"Global Source/binder choice audit budget");}for(Table t:m.relations.values()){w.run();require(++tables<=l.policy.cells&&t!=null&&t.exceptions.size()<=l.policy.cells-exceptions,"Global relation/default/exception audit budget");exceptions+=t.exceptions.size();}}
  // Preflight EVERY table/row/binder before any truth check or receipt.
  for(Snapshot cut:cuts){ContextRelationalInterpretation m=l.models.get(Cut.of(cut));model(m,l.policy,w);Set<Signature> vocabulary=new HashSet<>();Set<Binder> witnesses=new HashSet<>();for(Entry e:b.x.primary)shape(e,m,vocabulary,witnesses,w);if(cut!=b.x)for(Entry e:cut.primary)shape(e,m,vocabulary,witnesses,w);require(m.relations.keySet().containsAll(vocabulary)&&m.witnesses.keySet().equals(witnesses),"Complete original signatures/Source witnesses required");}
  for(Snapshot cut:cuts){ContextRelationalInterpretation m=l.models.get(Cut.of(cut));for(Entry e:b.x.primary)originalTruth(e,m,w);if(cut!=b.x)for(Entry e:cut.primary)originalTruth(e,m,w);}return new OriginalReceipt(l);
 }
 private static void take(Ledger l,int[] index,Kind kind,Cut cut,Object carrier,Support support,Runnable w){w.run();require(index[0]<l.obligations.size()&&index[0]<l.policy.extension.audit.obligations,"Complete actual final manifest required");Obligation o=l.obligations.get(index[0]++);require(o!=null&&o.kind==kind&&o.cut.equals(cut)&&o.carrier==carrier&&o.support==support,"Different final carrier/Source alternative/owner");}
 private static Residual actual(Obligation o){switch(o.kind){case UNIT:return ((ContextUniversalSignedUnitExchange.Unit)o.carrier).clause;case COMPOUND:return ((ContextUniversalCompoundExchange.ResidualProof)o.carrier).clause;case TERMINAL:return ((ContextUniversalFrozenConstraints.Proof)o.carrier).clause;default:throw new IllegalStateException("Actual residual required");}}
 private static void origin(Origin o,Set<Origin> origins,Map<Source,Integer> bundles,Runnable w){w.run();require(o!=null&&o.binder>=0&&bundles.containsKey(o.source)&&o.binder<bundles.get(o.source),"Actual original Source/binder Origin required");origins.add(o);}
 private static void finalShape(Obligation o,ContextRelationalInterpretation m,Set<Signature> vocabulary,Set<Origin> origins,Map<Source,Integer> bundles,Runnable w){if(o.kind==Kind.COMMON||o.kind==Kind.PRIVATE){Item i=(Item)o.carrier;relation(m,i.atom.predicate,i.atom.arguments.size(),vocabulary,w);for(Slot s:i.atom.arguments){w.run();if(s.origin!=null){require(s.value==null,"Origin cannot alias constant");origin(s.origin,origins,bundles,w);}else fixed(m,s.value,w);}return;}Residual c=actual(o);require(c!=null&&!c.literals.isEmpty()&&c.literals.size()<=8,"Whole actual final relational residual required");Set<Integer> ids=new HashSet<>();Set<Origin> os=new HashSet<>();for(org.kanger.ContextUniversalInputResiduals.Literal a:c.literals){relation(m,a.predicate,a.arguments.size(),vocabulary,w);for(org.kanger.ContextUniversalInputResiduals.Term t:a.arguments){w.run();require(t.variable>=-1,"Valid final variable slot required");if(t.variable>=0){require(t.origin==null&&t.value==null,"Final variable cannot alias Origin/constant");ids.add(t.variable);}else if(t.origin!=null){require(t.value==null,"Origin cannot alias constant");origin(t.origin,origins,bundles,w);os.add(t.origin);}else fixed(m,t.value,w);}}require(ids.equals(c.variables)&&os.equals(c.origins),"Complete actual residual variable/Origin identities required");}
 private static void finalTruth(Obligation o,ContextRelationalInterpretation m,Runnable w){w.run();if(o.kind==Kind.COMMON||o.kind==Kind.PRIVATE){Item i=(Item)o.carrier;List<Integer> tuple=new ArrayList<>();for(Slot s:i.atom.arguments){w.run();tuple.add(s.origin==null?fixed(m,s.value,w):m.denotations.get(s.origin));}require(m.relations.get(new Signature(i.atom.predicate,i.atom.arguments.size())).holds(tuple,w)==i.atom.positive,"Actual final relational atom false");return;}Residual c=actual(o);boolean uniform=true,knownTrue=false;for(org.kanger.ContextUniversalInputResiduals.Literal a:c.literals){w.run();Table t=m.relations.get(new Signature(a.predicate,a.arguments.size()));uniform&=t.exceptions.isEmpty();knownTrue|=t.exceptions.isEmpty()&&t.otherwise==a.positive;}if(knownTrue)return;require(!uniform,"Uniform actual final relational clause false");
  // Independently implemented mixed-radix traversal, distinct from original DFS.
  List<Integer> ids=new ArrayList<>(c.variables);Map<Integer,Integer> slot=new HashMap<>();for(int i=0;i<ids.size();i++){w.run();slot.put(ids.get(i),i);}int[] values=new int[ids.size()];boolean more=true;while(more){w.run();boolean yes=false;for(org.kanger.ContextUniversalInputResiduals.Literal a:c.literals){List<Integer> tuple=new ArrayList<>();for(org.kanger.ContextUniversalInputResiduals.Term t:a.arguments){w.run();tuple.add(t.variable>=0?values[slot.get(t.variable)]:t.origin!=null?m.denotations.get(t.origin):fixed(m,t.value,w));}yes|=m.relations.get(new Signature(a.predicate,a.arguments.size())).holds(tuple,w)==a.positive;}require(yes,"Cartesian actual final relational clause false");more=false;for(int i=0;i<values.length;i++){w.run();if(++values[i]<=m.points.size()){more=true;break;}values[i]=0;}}
 }
 static FinalReceipt finalModel(Ledger l,OriginalReceipt original,int maximumWork){require(original!=null&&original.ledger==l,"Exact immutable original relational interpretation required");original(l,maximumWork);ContextSignedWitnessNativeBranch.Receipt b=l.branch;require(b.status==ContextSignedWitnessNativeBranch.Status.QUIESCENT_SUPPLIED&&b.termination!=null&&b.termination.result.stopping!=null,"Actual completed branch required");ContextSignedWitnessNativeBranchAudit.check(b,b.x,b.foreign,b.policy,maximumWork,l.policy.extension.audit.capacity);Runnable w=ContextGroundProductionRounds.budget(maximumWork);ContextSignedWitnessStop.Receipt stop=b.termination.result.stopping;ContextSignedWitnessContinuationScope.Receipt scope=b.termination.result.output;require(stop.terminal.scope==scope&&l.models.keySet().equals(stop.terminal.checks.keySet()),"Exact original/final cut set required");int[] index={0};for(Cut c:stop.terminal.checks.keySet()){for(Item i:scope.current().packet.items)for(Support s:i.proofs)take(l,index,Kind.COMMON,c,i,s,w);PrivatePool pool=scope.current().privatePools.get(c);if(pool!=null)for(Item i:pool.local.items)for(Support s:i.proofs)take(l,index,Kind.PRIVATE,c,i,s,w);for(ContextUniversalSignedUnitExchange.Unit u:stop.units.units)take(l,index,Kind.UNIT,c,u,u.support,w);for(ContextUniversalCompoundExchange.ResidualProof r:stop.compounds.clauses)take(l,index,Kind.COMPOUND,c,r,r.support,w);for(ContextUniversalFrozenConstraints.Proof r:stop.terminal.checks.get(c).proofs)take(l,index,Kind.TERMINAL,c,r,r.support,w);}require(index[0]==l.obligations.size(),"No extra final obligation/Source alternative");Map<Source,Integer> bundles=new HashMap<>();for(Row row:l.rows)if(row.entry.bundle!=null)bundles.put(row.entry.source,row.entry.bundle.witnesses);
  Map<Cut,Set<Signature>> vocabularies=new LinkedHashMap<>();Map<Cut,Set<Origin>> origins=new LinkedHashMap<>();for(Cut cut:l.models.keySet()){vocabularies.put(cut,new HashSet<>());origins.put(cut,new HashSet<>());ContextRelationalInterpretation m=l.models.get(cut);Set<Binder> ws=new HashSet<>();for(Entry e:b.x.primary)shape(e,m,vocabularies.get(cut),ws,w);for(Snapshot foreign:b.foreign)if(Cut.of(foreign).equals(cut))for(Entry e:foreign.primary)shape(e,m,vocabularies.get(cut),ws,w);}for(Obligation o:l.obligations)finalShape(o,l.models.get(o.cut),vocabularies.get(o.cut),origins.get(o.cut),bundles,w);
  int imported=0;for(Cut cut:l.models.keySet()){ContextRelationalInterpretation m=l.models.get(cut);require(m.relations.keySet().equals(vocabularies.get(cut))&&m.denotations.keySet().equals(origins.get(cut)),"Exact final relation/Origin coverage, no discarded alternative");Set<Binder> retained=new HashSet<>();for(Map.Entry<Origin,Integer> e:m.denotations.entrySet()){origin(e.getKey(),new HashSet<>(),bundles,w);Integer point=e.getValue();require(point!=null&&point>=0&&point<m.points.size(),"Concrete named final Origin denotation required");if(m.witnesses.containsKey(new Binder(e.getKey()))){require(point.equals(m.witnesses.get(new Binder(e.getKey()))),"Original correlated binder cannot change at final barrier");retained.add(new Binder(e.getKey()));}else require(++imported<=l.policy.extension.origins,"Global imported Source/binder denotation audit budget");}require(retained.equals(m.witnesses.keySet()),"ALL original binders retained in actual final inventory");}
  for(Obligation o:l.obligations)finalTruth(o,l.models.get(o.cut),w);return new FinalReceipt(l,original);
 }
 static void check(FinalReceipt receipt,int work){require(receipt!=null,"Actual original AND final relational model receipt required");finalModel(receipt.ledger,receipt.original,work);}
}
